// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The doctor's request for blood for a patient of an admission or an emergency visit. */
export interface BloodRequestIn {
  admission_id?: number | null;
  er_visit_id?: number | null;
  /** The operation it is for, if any */
  booking_id?: number | null;
  component: "WholeBlood" | "RedCells" | "FreshFrozenPlasma" | "Cryoprecipitate" | "Platelets";
  units_requested: number;
  urgency: "Routine" | "Urgent" | "Emergency";
  indication: string;
  /** The patient's transfusion consent of this stay, Given (signed, or the doctor's emergency note): GET /consents?patient_id= */
  consent_id: number;
  /** Emergency only: the attending doctor's note authorising blood before the compatibility test (II C manual p159). Leave out for every other request */
  uncrossmatched_note?: string | null;
}

