/** Request blood — POST /api/v1/blood/requests (who may call: holders of blood.request). */
export function createRequest(body: BloodRequestIn): Promise<BloodRequestDetailOut> {
  return api<BloodRequestDetailOut>("POST", `/blood/requests`, body, { idempotent: true });
}

/** Blood requests — GET /api/v1/blood/requests (who may call: holders of blood.view). */
export function worklistBloodRequests(query?: { status?: "Open" | "Closed" | "Cancelled" | null; patient_id?: number | null; limit?: number; before_id?: number | null }): Promise<BloodRequestOut[]> {
  return api<BloodRequestOut[]>("GET", withQuery(`/blood/requests`, query), undefined);
}

/** One blood request — GET /api/v1/blood/requests/{request_id} (who may call: holders of blood.view). */
export function getRequest(request_id: number): Promise<BloodRequestDetailOut> {
  return api<BloodRequestDetailOut>("GET", `/blood/requests/${request_id}`, undefined);
}

/** Close a blood request (done) — POST /api/v1/blood/requests/{request_id}/close (who may call: holders of blood.request or blood.bank.operate). */
export function closeRequest(request_id: number, body: RequestCloseIn): Promise<BloodRequestDetailOut> {
  return api<BloodRequestDetailOut>("POST", `/blood/requests/${request_id}/close`, body);
}

/** Cancel a blood request — POST /api/v1/blood/requests/{request_id}/cancel (who may call: holders of blood.request). */
export function cancelRequest(request_id: number, body: RequestCloseIn): Promise<BloodRequestDetailOut> {
  return api<BloodRequestDetailOut>("POST", `/blood/requests/${request_id}/cancel`, body);
}

